<template>
  <div class="page-container gpm-page">
    <div class="page-head"><div><h2>地块管理</h2><p>查看青贮饲料种植地块台账，地块关联主体统一在种植主体管理中维护。</p></div></div>
    <div class="panel">
      <div class="panel-title"><span class="title-text">地块台账</span><span class="title-extra">共 {{ plots.length }} 块</span></div>
      <el-form :inline="true" class="filters"><el-form-item label="关键字"><el-input v-model="filters.keyword" clearable placeholder="地块名称/编号/主体" /></el-form-item><el-form-item label="来源"><el-select v-model="filters.source" clearable placeholder="全部" style="width:140px"><el-option label="确权地块" value="确权"/><el-option label="流转地块" value="流转"/></el-select></el-form-item><el-form-item label="关联状态"><el-select v-model="filters.status" clearable placeholder="全部" style="width:140px"><el-option label="已关联" value="已关联"/><el-option label="待确认" value="待确认"/></el-select></el-form-item><el-button type="primary" @click="loadPlots">查询</el-button><el-button @click="reset">重置</el-button></el-form>
      <el-table :data="plots" stripe height="calc(100vh - 300px)"><el-table-column prop="id" label="地块编号" width="130"/><el-table-column prop="name" label="地块名称" min-width="170" show-overflow-tooltip/><el-table-column prop="areaMu" label="地块面积(亩)" width="110"/><el-table-column prop="nameColor" label="名称颜色" width="90"><template #default="{ row }"><span class="color-dot" :style="{ backgroundColor: row.nameColor || '#409eff' }"/>{{ row.nameColor || '默认' }}</template></el-table-column><el-table-column prop="unitName" label="所属单位" min-width="140" show-overflow-tooltip/><el-table-column prop="manager" label="经营人员" width="100"/><el-table-column prop="cropName" label="种植作物" width="100"/><el-table-column prop="variety" label="种植品种" width="110"/><el-table-column prop="purpose" label="地块用途" width="110"/><el-table-column prop="plotType" label="地块类型" width="100"/><el-table-column prop="location" label="地块经纬度" min-width="160" show-overflow-tooltip/><el-table-column label="关联状态" width="100"><template #default="{ row }"><el-tag size="small" :type="row.relationStatus === '已关联' ? 'success' : 'warning'">{{ row.relationStatus }}</el-tag></template></el-table-column><el-table-column label="操作" width="100" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="openView(row)">查看详情</el-button></template></el-table-column></el-table><el-empty v-if="!plots.length" description="暂无青贮种植地块" />
    </div>
    <el-drawer v-model="visible" :title="drawerTitle" size="480px"><el-descriptions v-if="current" :column="1" border><el-descriptions-item label="地块编号">{{ current.id }}</el-descriptions-item><el-descriptions-item label="地块名称">{{ current.name }}</el-descriptions-item><el-descriptions-item label="地块面积">{{ current.areaMu }} 亩</el-descriptions-item><el-descriptions-item label="名称颜色"><span class="color-dot" :style="{ backgroundColor: current.nameColor || '#409eff' }"/>{{ current.nameColor || '默认' }}</el-descriptions-item><el-descriptions-item label="所属单位">{{ current.unitName || current.regionName }}</el-descriptions-item><el-descriptions-item label="经营人员">{{ current.manager || '暂无' }}</el-descriptions-item><el-descriptions-item label="种植作物">{{ current.cropName || '未种植' }}</el-descriptions-item><el-descriptions-item label="种植品种">{{ current.variety || '暂无' }}</el-descriptions-item><el-descriptions-item label="地块用途">{{ current.purpose || '暂无' }}</el-descriptions-item><el-descriptions-item label="地块类型">{{ current.plotType || '暂无' }}</el-descriptions-item><el-descriptions-item label="地块经纬度">{{ current.location || current.centerText || '暂无' }}</el-descriptions-item><el-descriptions-item label="地块轮廓">{{ current.boundary || '暂无' }}</el-descriptions-item><el-descriptions-item label="经营主体">{{ current.subjectName || '未关联' }}</el-descriptions-item></el-descriptions><template #footer><el-button @click="visible=false">关闭</el-button></template></el-drawer>
  </div>
</template>
<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { fetchSilPlots } from '@/api/sil'
import { useUserStore } from '@/stores/user'
const userStore = useUserStore(); const plots = ref([]); const visible = ref(false); const current = ref(null); const filters = reactive({ keyword: '', source: '', status: '' }); const drawerTitle = computed(() => `地块详情${current.value?.name ? `：${current.value.name}` : ''}`); const cropName = (crop) => ({ silage_corn: '青贮玉米', alfalfa: '苜蓿' }[crop] || crop || '—'); const loadPlots = async () => { const data = await fetchSilPlots(userStore.role); plots.value = data.map((plot) => ({ ...plot, name: plot.name || plot.plotName, areaMu: Number(plot.areaMu || plot.area || 0), nameColor: plot.nameColor || '#409eff', unitName: plot.unitName || plot.regionName || plot.regionCode || '—', cropName: cropName(plot.crop), location: plot.location || (plot.center ? `${Number(plot.center[0]).toFixed(5)}, ${Number(plot.center[1]).toFixed(5)}` : ''), relationStatus: plot.relationStatus || (plot.subjectId || plot.subjectName ? '已关联' : '待确认') })).filter((row) => (!filters.keyword || `${row.id}${row.name}${row.subjectName}`.includes(filters.keyword)) && (!filters.source || row.source === filters.source) && (!filters.status || row.relationStatus === filters.status)) }; const reset = () => { Object.assign(filters, { keyword: '', source: '', status: '' }); loadPlots() }; const openView = (row) => { current.value = row; visible.value = true }; onMounted(loadPlots)
</script>
<style scoped lang="scss">.gpm-page{gap:12px;overflow:auto}.page-head{display:flex;justify-content:space-between;align-items:flex-start}.page-head h2{margin:4px 0;color:var(--ah-text);font-size:22px}.page-head p{color:var(--ah-text-secondary);font-size:13px}.filters{display:flex;align-items:center;flex-wrap:wrap}.filters :deep(.el-form-item){margin-bottom:12px;margin-right:12px}.color-dot{display:inline-block;width:12px;height:12px;margin-right:5px;border:1px solid #dcdfe6;border-radius:50%;vertical-align:-1px}</style>
